using System.IO;
using System.Diagnostics;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows.Media.Imaging;
using RAWSelectionAssistant.Core.Models;
using RAWSelectionAssistant.Core.Services.Projects;
using RAWSelectionAssistant.Core.Utilities;
using RAWSelectionAssistant.Services;
using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public sealed class PlanningBoundedThumbnailTests
{
    static string Fixture(string name)=>Path.Combine(TestResources.Root,"tests","fixtures","planning-owned-jpeg",name);
    [TestMethod]public Task BoundedExifCacheIsPngAndEveryHitStillVerifiesSource()=>RunSta(async()=>
    {
        EnsureTestApplication();using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);await f.Vm.AddDocumentReferencesAsync([new(Guid.NewGuid(),ShotReferenceKind.General,ExternalReference:Fixture("orientation-6.jpg"))],true);var copy=(await f.Planning.LoadAsync(f.Id)).Document!.References.Single().ProjectCopy!;var cache=Path.Combine(f.Root,"cache");
        var a=PlanningOwnedReferenceImage.ReadThumbnail(copy,f.Id,copy.DocumentId,copy.ReferenceId,cache);Assert.IsFalse(a.CacheHit);Assert.AreEqual(48,a.Image.PixelWidth);Assert.AreEqual(80,a.Image.PixelHeight);Assert.AreEqual(".png",Path.GetExtension(a.Path));CollectionAssert.AreEqual(new byte[]{137,80,78,71,13,10,26,10},File.ReadAllBytes(a.Path)[..8]);var oldTime=File.GetLastWriteTimeUtc(a.Path);
        var b=PlanningOwnedReferenceImage.ReadThumbnail(copy,f.Id,copy.DocumentId,copy.ReferenceId,cache);Assert.IsTrue(b.CacheHit);Assert.AreEqual(oldTime,File.GetLastWriteTimeUtc(a.Path));
        await File.WriteAllBytesAsync(a.Path,[1,2,3]);var repaired=PlanningOwnedReferenceImage.ReadThumbnail(copy,f.Id,copy.DocumentId,copy.ReferenceId,cache);Assert.IsFalse(repaired.CacheHit);Assert.IsTrue(repaired.Image.IsFrozen);
        var source=PlanningProjectCopyStorage.Resolve(copy);await File.WriteAllBytesAsync(source,File.ReadAllBytes(Fixture("orientation-8.jpg")));Assert.Throws<InvalidDataException>(()=>PlanningOwnedReferenceImage.ReadThumbnail(copy,f.Id,copy.DocumentId,copy.ReferenceId,cache));File.Delete(source);Assert.Throws<FileNotFoundException>(()=>PlanningOwnedReferenceImage.ReadThumbnail(copy,f.Id,copy.DocumentId,copy.ReferenceId,cache));Assert.IsTrue(File.Exists(Fixture("orientation-6.jpg")));
    });
    [TestMethod]public Task BoundedDimensionsAllOrientationsAndCancelledRequestNeverPublishesCache()=>RunSta(async()=>
    {
        EnsureTestApplication();for(int o=1;o<=8;o++){var bytes=File.ReadAllBytes(Fixture($"orientation-{o}.jpg"));using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);await f.Vm.AddDocumentReferencesAsync([new(Guid.NewGuid(),ShotReferenceKind.General,ExternalReference:Fixture($"orientation-{o}.jpg"))],true);var c=(await f.Planning.LoadAsync(f.Id)).Document!.References.Single().ProjectCopy!;var image=PlanningOwnedReferenceImage.ReadBounded(c,f.Id,c.DocumentId,c.ReferenceId,40);Assert.AreEqual(o>=5?24:40,image.PixelWidth);Assert.AreEqual(o>=5?40:24,image.PixelHeight);using var cancel=new CancellationTokenSource();cancel.Cancel();Assert.Throws<OperationCanceledException>(()=>PlanningOwnedReferenceImage.ReadThumbnail(c,f.Id,c.DocumentId,c.ReferenceId,Path.Combine(f.Root,"never-cache"),cancel.Token));Assert.IsFalse(Directory.Exists(Path.Combine(f.Root,"never-cache")));}
    });
    [TestMethod]public Task CancelledRefreshAndFastProjectSwitchNeverShowPriorOwnedImages()=>RunSta(async()=>
    {
        EnsureTestApplication();using var f=await PlanningFoundationWpfTests.Fixture.Create();var first=f.Id;await f.Vm.LoadAsync(first);await f.Vm.AddDocumentReferencesAsync([new(Guid.NewGuid(),ShotReferenceKind.General,ExternalReference:Fixture("orientation-6.jpg"))],true);var next=Guid.NewGuid();await f.Projects.UpsertAsync(new(){Id=next,Name="B"});await f.Planning.UpdateDocumentAsync(next,new(){Title="B"},new());
        var old=f.Vm.RefreshDocumentReferencesAsync();await f.Vm.LoadAsync(next);await old;Assert.AreEqual(next,f.Vm.ProjectId);Assert.IsEmpty(f.Vm.AllProjectReferences);
        await f.Vm.LoadAsync(first);var view=new RAWSelectionAssistant.Views.PlanningCenterView{DataContext=f.Vm};await f.Vm.SelectContentSafelyAsync("参考图");view.Render();view.Measure(new System.Windows.Size(1100,800));view.Arrange(new System.Windows.Rect(0,0,1100,800));view.UpdateLayout();var one=f.Vm.RefreshDocumentReferencesAsync();var two=f.Vm.RefreshDocumentReferencesAsync();await Task.WhenAll(one,two);Assert.HasCount(1,f.Vm.AllProjectReferences);Assert.AreEqual(first,f.Vm.AllProjectReferences.Single().Link.ProjectCopy!.ProjectId);
        using var cancel=new CancellationTokenSource();cancel.Cancel();await f.Vm.RefreshDocumentReferencesAsync(cancel.Token);Assert.IsEmpty(f.Vm.AllProjectReferences);await f.Vm.RefreshDocumentReferencesAsync();Assert.HasCount(1,f.Vm.AllProjectReferences);view.DataContext=null;
    });
    [TestMethod]public Task LargeViewAndSummaryStayBoundedWithoutChangingOwnedSource()=>RunSta(async()=>
    {
        var fixtures=Environment.GetEnvironmentVariable("KITAO_LARGE_FIXTURES");if(string.IsNullOrWhiteSpace(fixtures)){Assert.Inconclusive("Explicit synthetic large fixture required");return;}EnsureTestApplication();using var f=await PlanningFoundationWpfTests.Fixture.Create();await f.Vm.LoadAsync(f.Id);var input=Path.Combine(fixtures,"large-0.jpg");await f.Vm.AddDocumentReferencesAsync([new(Guid.NewGuid(),ShotReferenceKind.General,ExternalReference:input)],true);var copy=(await f.Planning.LoadAsync(f.Id)).Document!.References.Single().ProjectCopy!;var original=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(input)));
        var large=PlanningOwnedReferenceImage.ReadBounded(copy,f.Id,copy.DocumentId,copy.ReferenceId,PlanningOwnedReferenceImage.LargeViewEdge);Assert.IsTrue(Math.Max(large.PixelWidth,large.PixelHeight)<=4096);Assert.IsTrue(large.PixelHeight>large.PixelWidth);
        var summary=PlanningSummaryOwnedImage.ReadImported(copy,f.Id,copy.DocumentId,700,1000);var bitmap=(BitmapSource)summary.Source;Assert.IsTrue(Math.Max(bitmap.PixelWidth,bitmap.PixelHeight)<=2048);Assert.IsTrue(bitmap.PixelHeight>bitmap.PixelWidth);Assert.AreEqual(original,Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(input))));
    });
    // Exactly the same test binary is used with before/after product DLL bindings in separate processes.
    [TestMethod]public Task SameFixtureLargeOpenWarmCacheAndMultiShotMeasurement()=>RunSta(async()=>
    {
        var fixtures=Environment.GetEnvironmentVariable("KITAO_LARGE_FIXTURES");var output=Environment.GetEnvironmentVariable("KITAO_THUMB_PERF_OUTPUT");if(string.IsNullOrWhiteSpace(fixtures)||string.IsNullOrWhiteSpace(output)){Assert.Inconclusive("Explicit fresh same-fixture performance output required");return;}
        EnsureTestApplication();using var f=await PlanningFoundationWpfTests.Fixture.Create();var refs=Directory.GetFiles(fixtures).Where(p=>p.EndsWith(".jpg")||p.EndsWith(".png")).Order().Select(p=>new PlanningDocumentReference(new(Guid.NewGuid(),ShotReferenceKind.General,ExternalReference:p,Title:Path.GetFileName(p)))).ToArray();await f.Planning.ImportProjectCopiesAsync(f.Id,refs,[]);var now=DateTimeOffset.UtcNow;await f.Shots.SaveCatalogAsync(new(f.Id,Enumerable.Range(0,36).Select(i=>new ProjectShot(Guid.NewGuid(),f.Id,i,"shot"+i,ProjectShotStatus.NotStarted,null,null,[refs[i%refs.Length].Source],now,now)).ToArray()));var next=Guid.NewGuid();await f.Projects.UpsertAsync(new(){Id=next,Name="EmptyB"});await f.Planning.UpdateDocumentAsync(next,new(){Title="B"},new());GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();
        var process=Process.GetCurrentProcess();long maxWorking=0,maxPrivate=0;using var stop=new CancellationTokenSource();var sampler=Task.Run(async()=>{while(!stop.IsCancellationRequested){process.Refresh();maxWorking=Math.Max(maxWorking,process.WorkingSet64);maxPrivate=Math.Max(maxPrivate,process.PrivateMemorySize64);try{await Task.Delay(5,stop.Token);}catch(OperationCanceledException){}}});var allocations=GC.GetTotalAllocatedBytes(true);var startWorking=process.WorkingSet64;var clock=Stopwatch.StartNew();await f.Vm.LoadAsync(f.Id);var cold=clock.Elapsed.TotalMilliseconds;Assert.HasCount(6,f.Vm.AllProjectReferences);Assert.HasCount(36,f.Vm.Shots);var imageProperty=typeof(RAWSelectionAssistant.ViewModels.PlanningReferenceItem).GetProperty("PreviewImage");if(imageProperty is not null)foreach(var row in f.Vm.AllProjectReferences){var bitmap=(BitmapSource?)imageProperty.GetValue(row);Assert.IsNotNull(bitmap);Assert.IsTrue(bitmap.PixelWidth<=512&&bitmap.PixelHeight<=512);var file=Path.Combine(output,Path.GetFileName(row.Link.Source.ExternalReference)+".thumbnail.png");Directory.CreateDirectory(output);using var stream=File.Create(file);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));encoder.Save(stream);}var paths=f.Vm.AllProjectReferences.Select(r=>r.PreviewPath).ToArray();Assert.IsTrue(paths.All(p=>p is not null));var times=paths.Select(p=>File.GetLastWriteTimeUtc(p!)).ToArray();clock.Restart();await (Task)typeof(RAWSelectionAssistant.ViewModels.PlanningCenterViewModel).GetMethods().Single(m=>m.Name=="RefreshDocumentReferencesAsync"&&m.GetParameters().Length==0).Invoke(f.Vm,null)!;var warm=clock.Elapsed.TotalMilliseconds;var unchanged=paths.Select((p,i)=>File.GetLastWriteTimeUtc(p!)==times[i]).Count(x=>x);var cacheProperty=typeof(RAWSelectionAssistant.ViewModels.PlanningReferenceItem).GetProperty("ThumbnailCacheHit");var hits=cacheProperty is null?0:f.Vm.AllProjectReferences.Count(x=>Equals(cacheProperty.GetValue(x),true));clock.Restart();await f.Vm.LoadAsync(next);var switchMs=clock.Elapsed.TotalMilliseconds;Assert.IsEmpty(f.Vm.AllProjectReferences);stop.Cancel();await sampler;
        Directory.CreateDirectory(output);await File.WriteAllTextAsync(Path.Combine(output,"MEASUREMENT.json"),JsonSerializer.Serialize(new{coldOpenMs=cold,warmRefreshMs=warm,switchToEmptyProjectMs=switchMs,cacheHitCount=hits,unchangedCacheFiles=unchanged,references=6,shots=36,width=6000,height=4000,startWorkingBytes=startWorking,peakWorkingBytes=maxWorking,peakPrivateBytes=maxPrivate,allocatedBytes=GC.GetTotalAllocatedBytes(true)-allocations,productAssembly=typeof(PlanningOwnedReferenceImage).Assembly.Location,coreAssembly=typeof(PlanningProjectStore).Assembly.Location,scope="Synthetic WPF/real stores in separate test process; same fixture, not native mouse/open benchmark"},new JsonSerializerOptions{WriteIndented=true}));
    });
}
